<?php $image_id = absint( get_theme_mod( 'kimpu_cta_background_image', 0 ) ); $style = ''; if ( $image_id ) { $url = wp_get_attachment_image_url( $image_id, 'full' ); if ( $url ) { $style = 'background-image:url(' . esc_url( $url ) . ');'; } } ?><section class="section <?php echo esc_attr( kimpu_homepage_section_classes( 'cta' ) ); ?> cta-layout-<?php echo esc_attr( kimpu_homepage_section_value( 'cta', 'layout', 'centered' ) ); ?>" id="call-to-action" style="<?php echo esc_attr( $style ); ?>"><div class="container cta-inner"><div><h2><?php echo esc_html( get_theme_mod( 'kimpu_cta_headline', '' ) ); ?></h2><p><?php echo esc_html( get_theme_mod( 'kimpu_cta_description', '' ) ); ?></p></div><div class="hero-actions"><?php if ( get_theme_mod( 'kimpu_cta_primary_text', '' ) && get_theme_mod( 'kimpu_cta_primary_url', '' ) ) : ?><a class="button" href="<?php echo esc_url( get_theme_mod( 'kimpu_cta_primary_url' ) ); ?>"><?php echo esc_html( get_theme_mod( 'kimpu_cta_primary_text' ) ); ?></a><?php endif; ?><?php if ( get_theme_mod( 'kimpu_cta_secondary_text', '' ) && get_theme_mod( 'kimpu_cta_secondary_url', '' ) ) : ?><a class="button button-outline" href="<?php echo esc_url( get_theme_mod( 'kimpu_cta_secondary_url' ) ); ?>"><?php echo esc_html( get_theme_mod( 'kimpu_cta_secondary_text' ) ); ?></a><?php endif; ?></div></div></section>
